-- COMPLEX FINTECH SYSTEM / MARIADB-MYSQL
CREATE DATABASE IF NOT EXISTS fintech_core;
USE fintech_core;
SET FOREIGN_KEY_CHECKS=0;

CREATE TABLE users (
  id BIGINT PRIMARY KEY ,
  email VARCHAR(255),
  phone VARCHAR(255),
  password_hash VARCHAR(255),
  status VARCHAR(255),
  country_code VARCHAR(255),
  created_at TIMESTAMP,


CREATE TABLE user_profiles (
  id BIGINT PRIMARY KEY ,
  user_id BIGINT,
  first_name VARCHAR(255),
  last_name VARCHAR(255),
  date_of_birth VARCHAR(255),
  occupation VARCHAR(255),
  risk_tier VARCHAR(255),
  created_at TIMESTAMP
) ;

CREATE TABLE kyc_profiles (
  id BIGINT PRIMARY KEY ,
  user_id BIGINT,
  status VARCHAR(255),
  provider VARCHAR(255),
  external_reference VARCHAR(255),
  verified_at TIMESTAMP,
  reviewed_at TIMESTAMP
) ;

CREATE TABLE kyc_documents (
  id BIGINT PRIMARY KEY ,
  kyc_id BIGINT,
  document_type VARCHAR(255),
  document_number_hash VARCHAR(255),
  storage_key VARCHAR(255),
  status VARCHAR(255),
  expires_at TIMESTAMP
) ;

CREATE TABLE user_addresses (
  id BIGINT PRIMARY KEY ,
  user_id BIGINT,
  address_type VARCHAR(255),
  line1 VARCHAR(255),
  city VARCHAR(255),
  state VARCHAR(255),
  postal_code VARCHAR(255),
  country_code VARCHAR(255)
) ;

CREATE TABLE devices (
  id BIGINT PRIMARY KEY ,
  user_id BIGINT,
  device_fingerprint VARCHAR(255),
  platform VARCHAR(255),
  app_version VARCHAR(255),
  trusted BOOLEAN,
  last_seen_at TIMESTAMP
) ;

CREATE TABLE sessions (
  id BIGINT PRIMARY KEY ,
  user_id BIGINT,
  device_id BIGINT,
  token_hash VARCHAR(255),
  expires_at TIMESTAMP,
  revoked_at VARCHAR(255),
  created_at TIMESTAMP
) ;

CREATE TABLE roles (
  id BIGINT PRIMARY KEY ,
  name VARCHAR(255),
  description VARCHAR(255),
  created_at TIMESTAMP
) ;

CREATE TABLE user_roles (
  id BIGINT PRIMARY KEY ,
  user_id BIGINT,
  role_id BIGINT,
  assigned_at VARCHAR(255)
) ;

CREATE TABLE accounts (
  id BIGINT PRIMARY KEY ,
  user_id BIGINT,
  account_number VARCHAR(255),
  account_type VARCHAR(255),
  currency_id BIGINT,
  status VARCHAR(255),
  created_at TIMESTAMP
) ;

CREATE TABLE account_members (
  id BIGINT PRIMARY KEY ,
  account_id BIGINT,
  user_id BIGINT,
  member_role VARCHAR(255),
  created_at TIMESTAMP
) ;

CREATE TABLE wallets (
  id BIGINT PRIMARY KEY ,
  account_id BIGINT,
  wallet_type VARCHAR(255),
  status VARCHAR(255),
  created_at TIMESTAMP
) ;

CREATE TABLE wallet_balances (
  id BIGINT PRIMARY KEY ,
  wallet_id BIGINT,
  available DECIMAL(20,6),
  pending DECIMAL(20,6),
  ledger DECIMAL(20,6),


CREATE TABLE currencies (
  id BIGINT PRIMARY KEY ,
  code VARCHAR(255),
  name VARCHAR(255),
  minor_unit VARCHAR(255),
  is_active VARCHAR(255)
) ;

CREATE TABLE exchange_rates (
  id BIGINT PRIMARY KEY ,
  base_currency_id BIGINT,
  quote_currency_id BIGINT,
  rate DECIMAL(20,6),
  provider VARCHAR(255),
  observed_at TIMESTAMP
) ;

CREATE TABLE payment_methods (
  id BIGINT PRIMARY KEY ,
  user_id BIGINT,
  method_type VARCHAR(255),
